"/* Design System & Root Variables */
:root {
  /* Colors - Light Theme (Default) */
  --bg-primary: #ffffff;
  --bg-secondary: #f8fafc;
  --bg-card: #ffffff;
  --bg-overlay: rgba(15, 23, 42, 0.4);
  --border-color: #e2e8f0;
  --text-primary: #0f172a;
  --text-secondary: #475569;
  --text-light: #64748b;

  --primary: #0d9488; /* Teal principal, fresco y premium */
  --primary-hover: #0f766e;
  --primary-light: #ccfbf1;
  --accent: #f43f5e; /* Coral/Rose de realce */
  --accent-hover: #e11d48;
  --whatsapp-green: #25d366;
  --whatsapp-green-hover: #128c7e;
  --star-gold: #f59e0b;
  --danger: #ef4444;
  --success: #22c55e;

  /* Layout & Spacing */
  --header-height: 80px;
  --categories-height: 70px;
  --border-radius-sm: 8px;
  --border-radius-md: 16px;
  --border-radius-lg: 24px;
  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.08);
  --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.15), 0 8px 10px -6px rgba(0, 0, 0, 0.15);

  /* Fonts */
  --font-title: 'Outfit', -apple-system, sans-serif;
  --font-body: 'Inter', -apple-system, sans-serif;

  /* Transitions */
  --transition-fast: 0.15s ease;
  --transition-normal: 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

